INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "朱祁钰", "aliases": ["明景帝"], "era": "明", "birth_year": null, "death_year": null, "description": "明景帝，正統14年（1449年）九月，朱祁钰即皇帝位。", "biography": null, "status": "draft", "id": "beac1b51-89b3-5024-bf3a-2d45bc5afe2b"}, {"name": "梁珤", "aliases": ["保定伯梁珤", "梁缶"], "era": "明", "birth_year": null, "death_year": null, "description": "梁珤奉命接替王骥。", "biography": null, "status": "draft", "id": "341faff8-5d67-5789-92bc-4208bdaba6d2"}, {"name": "王来", "aliases": ["王來"], "era": "明", "birth_year": null, "death_year": null, "description": "王来奉命总督湖广、贵州军务。", "biography": null, "status": "draft", "id": "a5950c64-7d84-533e-aaaa-e6827cc87737"}, {"name": "何文渊", "aliases": ["何文淵"], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，景泰2年（年号对照1451年）七月，何文渊出任吏部尚书。", "biography": null, "status": "draft", "id": "27355cff-bfac-5145-9909-8afd7fac7e16"}, {"name": "林聪", "aliases": ["林聰"], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，成化3年（年号对照1467年）四月，林聪出任右都御史。", "biography": null, "status": "draft", "id": "ca5f4f12-f595-598a-b3e3-ff0f69ba7def"}, {"name": "也先", "aliases": ["瓦剌太师也先"], "era": "明", "birth_year": null, "death_year": null, "description": "也先所部为明廷防备对象。", "biography": null, "status": "draft", "id": "d9af0d41-e6b4-5de2-9de3-32e0f8826f3c"}, {"name": "徐有贞", "aliases": ["徐有貞"], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，景泰8年（1457年）正月，徐有贞以兵部尚书兼翰林学士身份入阁。", "biography": null, "status": "draft", "id": "a2c2c258-40a6-5fa1-b82d-a741f40d91fb"}, {"name": "朱见济", "aliases": ["懷獻太子"], "era": "明", "birth_year": null, "death_year": null, "description": "朱见济获立为皇太子。", "biography": null, "status": "draft", "id": "7f573a8b-cd4b-5a6e-a3ee-4de70f6bc670"}]'::jsonb)
