INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "明景帝在南郊祭祀天地", "description": "景泰四年正月辛未，明景帝朱祁钰在南郊举行祭祀天地的大典。", "start_year": 1453, "end_year": 1453, "time_original": "景泰四年正月辛未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "8fd16dd5-08e0-5174-bf76-89137a14e53b"}, {"title": "五开、清浪等地再有苗民起事，梁珤、王来征讨", "description": "景泰四年二月戊子，本纪记五开、清浪一带再次发生苗民起事，梁珤、王来率军征讨。", "start_year": 1453, "end_year": 1453, "time_original": "景泰四年二月戊子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "fad91e91-b4c9-516c-bb95-cf77d65ac038"}, {"title": "明廷免除江西上年灾区的秋粮", "description": "景泰四年二月庚戌，朝廷免除江西上年受灾地区应缴的秋粮。", "start_year": 1453, "end_year": 1453, "time_original": "景泰四年二月庚戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "a7b82370-0496-5404-8518-5742fc935573"}, {"title": "明廷在建宁开设银场", "description": "景泰四年三月戊寅，明廷在建宁开设银场。", "start_year": 1453, "end_year": 1453, "time_original": "景泰四年三月戊寅", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "011fa683-a1e7-5c9d-92ce-a4bc41cc8588"}, {"title": "明廷修筑沙湾黄河决口", "description": "景泰四年四月戊子，明廷组织修筑沙湾的黄河决口。", "start_year": 1453, "end_year": 1453, "time_original": "景泰四年四月戊子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "6ec7581b-7186-5627-8854-b8cc8f990031"}, {"title": "明廷调运南京仓粮赈济徐州", "description": "景泰四年四月，朝廷从南京粮仓调运粮食，赈济徐州。", "start_year": 1453, "end_year": 1453, "time_original": "景泰四年四月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "969e81ce-703a-5e8f-a78d-4e1c8bdfe93b"}, {"title": "明廷发放徐州、淮安仓粮赈济饥民", "description": "景泰四年五月丁巳，朝廷开徐州、淮安的粮仓，发放粮食赈济饥民。", "start_year": 1453, "end_year": 1453, "time_original": "景泰四年五月丁巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "3daa48c4-3d22-5787-818d-20d465c3b40c"}, {"title": "徐州再发洪水，明廷调运粮食赈济饥民", "description": "景泰四年五月甲戌，徐州再次发生洪水，民间饥荒加重。朝廷调支运和盐课储粮赈济。", "start_year": 1453, "end_year": 1453, "time_original": "景泰四年五月甲戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "983bbf33-9e29-57b9-a393-d1c309263d43"}, {"title": "明廷发放淮安仓粮赈济凤阳", "description": "景泰四年五月丁丑，朝廷调发淮安粮仓的存粮，赈济凤阳。", "start_year": 1453, "end_year": 1453, "time_original": "景泰四年五月丁丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "dddd3e0e-d634-57da-a0cf-bd71309325d2"}, {"title": "黄河在沙湾再次决口", "description": "景泰四年五月乙酉，黄河在沙湾再次决口。", "start_year": 1453, "end_year": 1453, "time_original": "景泰四年五月乙酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "8f0c6b2d-98a5-57b6-a019-921459345e6b"}, {"title": "何文渊被投入监狱，随后获释，获准退休", "description": "景泰4年（年号对照1453年）六月，何文渊被投入监狱，随后获释，获准退休。", "start_year": 1453, "end_year": 1453, "time_original": "景泰4年（年号对照1453年）六月；公元年核为1453年。", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "ab3de641-5af5-5dd0-a769-82387053d6da"}, {"title": "明廷安葬土木、大同和紫荆关暴露的遗骸", "description": "景泰四年六月辛亥，明廷命人收殓并安葬留在土木、大同和紫荆关的遗骸。", "start_year": 1453, "end_year": 1453, "time_original": "景泰四年六月辛亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "62cf2d78-47f4-56f4-a079-ad39c5ad412b"}, {"title": "明廷暂停各项非紧急工役", "description": "景泰四年七月庚辰，朝廷下令暂停各项非紧急工役。", "start_year": 1453, "end_year": 1453, "time_original": "景泰四年七月庚辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "016d44cf-19bd-5a96-902a-0dacfd6a33ca"}, {"title": "明廷赈济河南饥民", "description": "景泰四年八月己丑，朝廷赈济河南的饥民。", "start_year": 1453, "end_year": 1453, "time_original": "景泰四年八月己丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "492ec4ce-2fd7-539f-b550-4f98e1c59ddb"}, {"title": "也先自立为可汗", "description": "景泰四年八月甲午，《明史》本纪记瓦剌太师也先自立为可汗。", "start_year": 1453, "end_year": 1453, "time_original": "景泰四年八月甲午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "b7732179-3465-5c21-b465-dbb7fed1abad"}, {"title": "明廷命各地镇守、巡抚官督促农桑", "description": "景泰四年十月庚寅，朝廷下诏，命各地镇守官和巡抚督促耕作及蚕桑生产。", "start_year": 1453, "end_year": 1453, "time_original": "景泰四年十月庚寅", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "d251fe05-9b0a-5862-981f-d17c92734c99"}, {"title": "徐有贞受命治理沙湾河患", "description": "景泰四年十月甲午，朝廷任命谕德徐有贞为左佥都御史，派他治理沙湾黄河决口。《英宗实录》作右佥都御史，卷末校记保留两种写法。", "start_year": 1453, "end_year": 1453, "time_original": "景泰四年十月甲午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "05cfb0e1-cd17-5cfc-ab23-f31fd4191813"}, {"title": "也先派使者到明朝", "description": "景泰四年十月戊戌，本纪记也先派遣使者到明朝。", "start_year": 1453, "end_year": 1453, "time_original": "景泰四年十月戊戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "ced92ec5-2583-53fb-9655-4c360c80d041"}, {"title": "皇太子朱见济去世", "description": "景泰四年十一月辛未，皇太子朱见济去世。", "start_year": 1453, "end_year": 1453, "time_original": "景泰四年十一月辛未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "030a3718-78d3-551e-b1be-b31948b8f3b2"}, {"title": "明廷豁免山东灾区税粮", "description": "景泰四年十二月乙未，朝廷免除山东受灾地区应缴的税粮。", "start_year": 1454, "end_year": 1454, "time_original": "景泰四年十二月乙未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "7a15452b-6e5c-5ef6-8fc9-3fe6c18c4180"}, {"title": "明廷赏赐边防军士", "description": "景泰四年十二月乙巳，朝廷赏赐边防军士。", "start_year": 1454, "end_year": 1454, "time_original": "景泰四年十二月乙巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "a94b3d1f-bca4-56f0-9005-dabfee38d4ac"}, {"title": "本纪汇记景泰四年多地入贡", "description": "景泰四年，琉球中山、安南、爪哇、日本、占城、哈密和瓦剌入贡。 按原历纪年，事情发生在公元1453至1454年之间。", "start_year": null, "end_year": null, "time_original": "景泰四年", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "842c9bb4-e2b1-5bd0-a0f2-60f8a112b184"}, {"title": "王文恢复任职", "description": "景泰4年（1453年）九月，王文恢复任职。", "start_year": 1453, "end_year": 1453, "time_original": "景泰4年（1453年）九月", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "d07995e7-af04-5f65-8f47-2e7481a07f51"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

